527	\begin{fact}\label{fact:obvious-vector-fact}
528	For two vectors $\ket{\psi_1}, \ket{\psi_2}$, 
529	$\displaystyle
530	\Vert \ket{\psi_1} + \ket{\psi_2} \Vert^2 \leq 2 \Vert \ket{\psi_1} \Vert^2 + 2 \Vert \ket{\psi_2} \Vert^2.
531	$
532	\end{fact}
533	
534	\begin{fact}\label{fact:measurement-sub-measurement-switcheroo}
535	Let $\{A_a\}$ be a measurement. Then
536	\begin{equation*}
537	\sum_a \Vert A_{a} \ket{\psi}\Vert^2 \leq\Vert \ket{\psi} \Vert^2.
538	\end{equation*}
539	\end{fact}
540	\begin{proof}
541	If $\{A_a\}$ is a measurement, then
542	\begin{equation*}
543	\sum_a \Vert A_{a} \ket{\psi}\Vert^2
544	= \sum_a \tr( A_a A_{a} \ket{\psi}\bra{\psi})
545	\leq \tr(I \cdot \ket{\psi}\bra{\psi}) = \Vert \ket{\psi}\Vert^2.\qedhere
546	\end{equation*}
547	\end{proof}
