592	\begin{fact}\label{fact:swap-dists}
593	Let $\calD, \calD'$ be two distributions such that $d_{\mathrm{TV}}(\calD, \calD') \leq \epsilon$.
594	Let $\{A_a^x\}$ and $\{B_a^x\}$ be measurements,
595	and suppose $A_a^x \approx_\delta B_a^x$ with respect to~$\calD$. Then $A_a^x \approx_{\delta + \epsilon} B_a^x$ with respect to~$\calD'$.
596	\end{fact}
597	\begin{proof}
598	By the definition of total variation distance,
599	for any set of numbers $\{\nu_x\}$ satisfying $0 \leq \nu_x \leq c$,
600	the expectations under the two distributions are similar:
601	\begin{equation*}
602	|\E_{\bx \sim \calD} [\nu_\bx] - \E_{\bx \sim \calD'}[\nu_{\bx}]| \leq c \cdot \epsilon.
603	\end{equation*}
604	We will take for our numbers $\nu_x = \sum_a \Vert (A_{a}^{x} - B_{a}^{x} ) \ket{\psi}\Vert^2$,
605	which is always less than~$4$ by \Cref{fact:easy-bound}.
606	As a result,
607	\begin{equation*}
608	\E_{\bx \sim \calD'} \nu_{\bx} \leq \E_{\bx \sim \calD} \nu_{\bx} + 4 \eps \leq \delta + 4 \eps.
609	\end{equation*}
610	This is $O(\delta + \epsilon)$, which proves the fact.

